ecc_agent_script.script:
(function() {

    var data = JSON.parse(payload);

    var prompt = "Summarize incident:\n\n" +
        "Problem:\nActions Taken:\nResolution:\n\n" +
        "Short Description: " + data.short_description + "\n" +
        "Description: " + data.description + "\n" +
        "Work Notes: " + data.work_notes;

    var body = {
        model: "llama3",
        prompt: prompt,
        stream: false
    };

    var r = new sn_ws.RESTMessageV2();
    r.setEndpoint("http://localhost:11434/api/generate");
    r.setHttpMethod("POST");
    r.setRequestHeader("Content-Type", "application/json");
    r.setRequestBody(JSON.stringify(body));

    r.setMIDServer("Crank Mid Server");

    var response = r.execute();
    response.waitForResponse(60);

    var responseBody = JSON.parse(response.getBody());

    return JSON.stringify({
        sys_id: data.sys_id,
        summary: responseBody.response
    });

})();
